  'Move slowly left → right': { gu:'ધીમે ડાબેથી → જમણે ખસેડો', hi:'धीरे बाएँ → दाएँ ले जाएँ', fr:'Déplacez lentement de gauche → droite' },
  'Multiple identical items stay multiple': { gu:'એકસરખી ઘણી વસ્તુઓ અલગ જ ગણાય છે', hi:'एक जैसी कई वस्तुएँ अलग-अलग ही गिनी जाती हैं', fr:'Plusieurs articles identiques restent plusieurs articles' },
