  'optional': { gu:'વૈકલ્પિક', hi:'वैकल्पिक', fr:'facultatif' },
  'Updates the household forecast': { gu:'ઘરેલુ ફોરકાસ્ટ અપડેટ કરે છે', hi:'घरेलू पूर्वानुमान अपडेट करता है', fr:'Met à jour les prévisions du foyer' },
  'Private': { gu:'ખાનગી', hi:'निजी', fr:'Privée' },
  'Edit my recipe': { gu:'મારી રેસીપી સંપાદિત કરો', hi:'मेरी रेसिपी संपादित करें', fr:'Modifier ma recette' },
  'Only confirmed items change': { gu:'ફક્ત ખાતરી કરેલી વસ્તુ બદલાય છે', hi:'केवल पुष्टि किए आइटम बदलते हैं', fr:'Seuls les éléments confirmés changent' },
  'Share recipe to House Chat': { gu:'રેસીપી House Chat માં શેર કરો', hi:'रेसिपी House Chat में साझा करें', fr:'Partager la recette dans le chat du foyer' },
  'Expired items are never consumed here': { gu:'સમાપ્ત વસ્તુ અહીં ક્યારેય વપરાયેલી ગણાતી નથી', hi:'एक्सपायर आइटम यहाँ कभी उपभोग नहीं माने जाते', fr:'Les articles expirés ne sont jamais considérés comme consommés ici' },
