  // Expense account workspace
  '+ New account': { gu:'+ નવું એકાઉન્ટ', hi:'+ नया खाता', fr:'+ Nouveau compte' },
  'ACCOUNT ACTIVITY': { gu:'એકાઉન્ટ પ્રવૃત્તિ', hi:'खाता गतिविधि', fr:'ACTIVITÉ DU COMPTE' },
