  "Template updated.": { gu:"ટેમ્પલેટ અપડેટ થયું.", hi:"टेम्पलेट अपडेट हुआ।", fr:"Modèle mis à jour." },
  "Template created. You can keep it private or share it with the community.": { gu:"ટેમ્પલેટ બનાવાયું. તેને ખાનગી રાખો અથવા કમ્યુનિટી સાથે શેર કરો.", hi:"टेम्पलेट बनाया गया। इसे निजी रखें या समुदाय से साझा करें।", fr:"Modèle créé. Vous pouvez le garder privé ou le partager avec la communauté." },
  "Reusable household template": { gu:"ફરી વાપરી શકાય તેવું ઘરેલુ ટેમ્પલેટ", hi:"पुन: उपयोग योग्य घरेलू टेम्पलेट", fr:"Modèle de foyer réutilisable" },
