  "New users 30 days": { gu:"30 દિવસમાં નવા વપરાશકર્તા", hi:"30 दिनों में नए उपयोगकर्ता", fr:"Nouveaux utilisateurs sur 30 jours" },
  "24h activation": { gu:"24 કલાક સક્રિયતા", hi:"24h सक्रियता", fr:"Activation à 24 h" },
  "D1 retention": { gu:"D1 રિટેન્શન", hi:"D1 रिटेंशन", fr:"Rétention J1" },
