  "Video": { gu:"વિડિયો", hi:"वीडियो", fr:"Vidéo" },
  "Approval": { gu:"મંજૂરી", hi:"अनुमोदन", fr:"Approbation" },
  "Media retention": { gu:"મીડિયા રિટેન્શન", hi:"मीडिया रिटेंशन", fr:"Rétention des médias" },
  "Ephemeral / delete after analysis": { gu:"અસ્થાયી / વિશ્લેષણ પછી કાઢી નાખો", hi:"अस्थायी / विश्लेषण के बाद हटाएँ", fr:"Éphémère / supprimer après analyse" },
  "Deployment setting allows retention": { gu:"ડિપ્લોયમેન્ટ સેટિંગ રિટેન્શન મંજૂર કરે છે", hi:"डिप्लॉयमेंट सेटिंग रिटेंशन की अनुमति देती है", fr:"Le paramètre de déploiement autorise la conservation" },
